import traceback, logger_util

totalCertificates = "<%totalCertificates%>"

logger = logger_util.get_logger("Certificate Discovery Changes Detection",
                                "disocvery_changes_detection.log")

def trigger_payload():
    """
    Trigger payload for discovery of certificates.
    """
    try:
        DISCOVERY_NAME = "<%name%>"
        discovery_payload = {"name": DISCOVERY_NAME, "startIndex" : 0, "maxSize" : 10}
        return discovery_payload
    except Exception as error:
        raise Exception(f"Error creating discovery payload: {error}")


if __name__ == "__main__":

    try:
        discovery_payload = trigger_payload()
        AVX::OUTPUT({"discovery_payload": discovery_payload})
    except Exception as error:
        logger.info(f" {error} - Details: {str(traceback.format_exc())}")
        AVX::LOG(f" {error} - Details: {str(traceback.format_exc())}")
        AVX::OUTPUT({"error": str(error)},2)
